/**
 * Point sets for `PointMorphField`.
 *
 * Each string is a flat, comma-separated `x,y,x,y,...` list in SVG-ish space
 * (origin at the centre, Y pointing down, roughly -0.5..0.5 on both axes).
 * The field negates Y in the vertex shader to get world space, multiplies
 * every coordinate by the shape's `scale`, and keeps each point with
 * probability `threshold`.
 *
 * The numbers are transcribed byte for byte from the design source; do not
 * reformat, round, or re-space them.
 */

/** One morph target: a point cloud plus how it is thinned and sized. */
export interface PointShape {
  /** Comma-separated `x,y,x,y,...` pairs. */
  points: string
  /** Uniform multiplier applied to every coordinate. */
  scale: number
  /** Probability (0..1) that any given point survives thinning. */
  threshold: number
}

